1	#!/usr/bin/env node
2	// Usage: todo add <title> [--due DATE] [--priority low|normal|high]
3	//        todo done <id>
4	//        todo list
5	// The list is stored in $TODO_FILE (default: ./todo.json).
6	import { existsSync } from "node:fs";
7	import { TodoList } from "../src/todo.js";
8	
9	const file = process.env.TODO_FILE ?? "todo.json";
10	const [cmd, ...args] = process.argv.slice(2);
11	
12	function fail(msg) {
13	  console.error(msg);
14	  process.exit(1);
15	}
16	
17	const list = existsSync(file) ? TodoList.load(file) : new TodoList();
18	
19	try {
20	  if (cmd === "add") {
21	    const opts = {};
22	    const words = [];
23	    for (let i = 0; i < args.length; i++) {
24	      if (args[i] === "--due") opts.due = args[++i];
25	      else if (args[i] === "--priority") opts.priority = args[++i];
26	      else words.push(args[i]);
27	    }
28	    const item = list.add(words.join(" "), opts);
29	    list.save(file);
30	    console.log(`added ${item.id}: ${item.title}`);
31	  } else if (cmd === "done") {
32	    const item = list.complete(Number(args[0]));
33	    list.save(file);
34	    console.log(`completed ${item.id}: ${item.title}`);
35	  } else if (cmd === "list") {
36	    for (const i of list.sorted()) {
37	      const due = i.due ? ` (due ${i.due.slice(0, 10)})` : "";
38	      console.log(`${i.id} [${i.done ? "x" : " "}] ${i.priority} ${i.title}${due}`);
39	    }
40	  } else {
41	    fail("usage: todo add <title> [--due DATE] [--priority P] | done <id> | list");
42	  }
43	} catch (e) {
44	  fail(e.message);
45	}
